/**
 * Generates a Power Apps Canvas app (.msapp) for the Application Catalog.
 *
 * Strategy: Reads blank app as ZIP base, replaces Controls JSON (the authoritative
 * source Power Apps actually reads) with properly structured control definitions.
 * YAML source files are regenerated by Power Apps on open — only JSON matters.
 *
 * Usage:
 *   node scripts/generate-powerapps.js
 *
 * After import:
 *   Data panel → Add data → SharePoint
 *   Site: https://soco365.sharepoint.com/sites/DataAnalytics-KruseConsulting
 *   List: Kruse Projects 2026
 */

const JSZip = require('jszip');
const fs = require('fs');
const path = require('path');

const BASE_APP = '/Users/dylanpincus/Downloads/Dummy App (1).msapp';
const OUT = path.resolve(__dirname, '../application-catalog.msapp');

// ---------------------------------------------------------------------------
// Template metadata (from reverse-engineering Controls/*.json in blank app)
// ---------------------------------------------------------------------------
const TPL = {
  screen:          { Id: 'http://microsoft.com/appmagic/screen',          Version: '1.0',    Name: 'screen' },
  label:           { Id: 'http://microsoft.com/appmagic/label',           Version: '2.5.1',  Name: 'label' },
  textInput:       { Id: 'http://microsoft.com/appmagic/text',            Version: '2.3.2',  Name: 'text' },
  button:          { Id: 'http://microsoft.com/appmagic/button',          Version: '2.2.0',  Name: 'button' },
  dropdown:        { Id: 'http://microsoft.com/appmagic/dropdown',        Version: '2.3.1',  Name: 'dropdown' },
  gallery:         { Id: 'http://microsoft.com/appmagic/gallery',         Version: '2.15.0', Name: 'gallery' },
  galleryTemplate: { Id: 'http://microsoft.com/appmagic/galleryTemplate', Version: '1.0',    Name: 'galleryTemplate' },
  appinfo:         { Id: 'http://microsoft.com/appmagic/appinfo',         Version: '1.0',    Name: 'appinfo' },
  hostControl:     { Id: 'http://microsoft.com/appmagic/hostcontrol',     Version: '1.6.0',  Name: 'hostControl' },
};

// ---------------------------------------------------------------------------
// UID counter — starts at 100 to avoid collisions with existing IDs (1-22)
// ---------------------------------------------------------------------------
let _uid = 100;
const uid = () => String(_uid++);

// ---------------------------------------------------------------------------
// Rule helper
// ---------------------------------------------------------------------------
function R(Property, InvariantScript, Category = 'Design', extra = {}) {
  return { Property, Category, InvariantScript: String(InvariantScript), RuleProviderType: 'Unknown', ...extra };
}

// ---------------------------------------------------------------------------
// Base control builder
// ---------------------------------------------------------------------------
function ctrl({ name, tpl, style, variant = '', parent, poi, rules, isData = false, children = [], dynProps }) {
  const obj = {
    Type: 'ControlInfo',
    Name: name,
    HasDynamicProperties: !!dynProps,
    Template: {
      Id: tpl.Id, Version: tpl.Version, LastModifiedTimestamp: '0', Name: tpl.Name,
      FirstParty: true, IsPremiumPcfControl: false, IsCustomGroupControlTemplate: false,
      CustomGroupControlTemplateName: '', IsComponentDefinition: false, OverridableProperties: {},
    },
    Index: 0,
    PublishOrderIndex: poi,
    VariantName: variant,
    LayoutName: '',
    MetaDataIDKey: '',
    PersistMetaDataIDKey: false,
    IsFromScreenLayout: false,
    StyleName: style,
    Parent: parent,
    IsDataControl: isData,
    AllowAccessToGlobals: true,
    OptimizeForDevices: 'Off',
    IsGroupControl: false,
    IsAutoGenerated: false,
    Rules: rules,
    ControlPropertyState: rules.map(r => r.Property),
    IsLocked: false,
    ControlUniqueId: uid(),
    Children: children,
  };
  if (dynProps) obj.DynamicProperties = dynProps;
  return obj;
}

// ---------------------------------------------------------------------------
// Label builder — includes all required ControlPropertyState fields
// ---------------------------------------------------------------------------
function lbl({ name, parent, poi, z, text, x, y, w, h,
  color = 'RGBA(50, 49, 48, 1)',
  fill  = 'RGBA(0, 0, 0, 0)',
  size  = 13,
  fw    = 'FontWeight.Normal',
  align = 'Align.Left',
  va    = 'VerticalAlign.Middle',
  overflow = 'Overflow.Hidden',
  bold = false,
  visible,
  isData = false,
}) {
  const rules = [
    R('Live',   'Live.Off',         'Data'),
    R('Text',   text,               'Data'),
    R('Role',   'TextRole.Default', 'Data'),
    R('Overflow', overflow),
    R('Color',              color),
    R('DisabledColor',      'RGBA(161, 159, 157, 1)'),
    R('PressedColor',       'Self.Color'),
    R('HoverColor',         'Self.Color'),
    R('BorderColor',        'RGBA(0, 0, 0, 0)'),
    R('DisabledBorderColor','RGBA(0, 0, 0, 0)'),
    R('PressedBorderColor', 'Self.BorderColor'),
    R('HoverBorderColor',   'Self.BorderColor'),
    R('BorderStyle',        'BorderStyle.None'),
    R('FocusedBorderColor', 'Self.BorderColor'),
    R('Fill',         fill),
    R('DisabledFill', 'RGBA(0, 0, 0, 0)'),
    R('PressedFill',  'Self.Fill'),
    R('HoverFill',    'Self.Fill'),
    R('Font',         "Font.'Segoe UI'"),
    R('FontWeight',   bold ? 'FontWeight.Bold' : fw),
    R('Align',        align),
    R('VerticalAlign',va),
    R('X', String(x)), R('Y', String(y)),
    R('Width', String(w)), R('Height', String(h)),
    R('DisplayMode', 'DisplayMode.Edit'),
    R('ZIndex', String(z)),
    R('LineHeight', '1.2'),
    R('BorderThickness', '2'),
    R('FocusedBorderThickness', '4'),
    R('Size', String(size)),
    R('Italic',        'false'),
    R('Underline',     'false'),
    R('Strikethrough', 'false'),
    R('PaddingTop',    '5'),
    R('PaddingRight',  '5'),
    R('PaddingBottom', '5'),
    R('PaddingLeft',   '5'),
  ];
  if (visible !== undefined) rules.push(R('Visible', String(visible)));
  return ctrl({ name, tpl: TPL.label, style: 'defaultLabelStyle', parent, poi, rules, isData });
}

// ---------------------------------------------------------------------------
// TextInput builder
// ---------------------------------------------------------------------------
