// ---------------------------------------------------------------------------
// Modify App (Controls/1.json) to set OnStart global variables
// ---------------------------------------------------------------------------
function buildAppControl(existingApp) {
  const app = JSON.parse(JSON.stringify(existingApp));
  // Add OnStart rule if not present
  if (!app.TopParent.Rules.find(r => r.Property === 'OnStart')) {
    app.TopParent.Rules.push(R('OnStart', 'Set(gSelected,Blank())', 'Behavior'));
    app.TopParent.ControlPropertyState.push('OnStart');
  }
  // Set start screen
  if (!app.TopParent.Rules.find(r => r.Property === 'StartScreen')) {
    app.TopParent.Rules.push(R('StartScreen', 'Screen1', 'Design'));
    app.TopParent.ControlPropertyState.push('StartScreen');
  }
  return app;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------
async function main() {
  if (!fs.existsSync(BASE_APP)) {
    console.error('Base app not found:', BASE_APP);
    process.exit(1);
  }

  const baseData = fs.readFileSync(BASE_APP);
  const zip = await JSZip.loadAsync(baseData);

  // Read existing Controls JSON
  const appJson    = JSON.parse(await zip.file('Controls\\1.json').async('string'));
  const screen1Json= JSON.parse(await zip.file('Controls\\4.json').async('string'));

  // Build modified App control
  const newAppJson = buildAppControl(appJson);

  // Build modified Screen1 (browse) - pass the existing TopParent to preserve boilerplate
  const newScreen1Json = { TopParent: buildBrowseScreen(screen1Json.TopParent) };

  // Build detail screen as a new Controls file
  const newDetailJson = buildDetailScreen();

  // Remove old YAML source files (they'll be regenerated by Power Apps)
  Object.keys(zip.files).forEach(f => {
    if ((f.startsWith('Src\\') || f.startsWith('Src/')) && f.endsWith('.pa.yaml')) {
      delete zip.files[f];
    }
  });

  // Write updated Controls JSON
  zip.file('Controls\\1.json', JSON.stringify(newAppJson, null, 2));
  zip.file('Controls\\4.json', JSON.stringify(newScreen1Json, null, 2));
  zip.file('Controls\\200.json', JSON.stringify(newDetailJson, null, 2));

  const buf = await zip.generateAsync({ type: 'nodebuffer', compression: 'DEFLATE' });
  fs.writeFileSync(OUT, buf);

  console.log('Generated:', OUT);
  console.log('\nImport: make.powerapps.com → Create → Open → Browse files');
  console.log('After import → Data panel → Add data → SharePoint');
  console.log('  Site: https://soco365.sharepoint.com/sites/DataAnalytics-KruseConsulting');
  console.log('  List: Kruse Projects 2026');
}

main().catch(console.error);
